#include <cstdio>
#include <cstdint>
#include <vector>

// 极简直接映射缓存模型：256 行 × 64 字节。统计"缓存行未命中"次数。
// 这是确定性模拟，与机器速度无关。
struct Cache {
    int nlines;
    std::vector<long long> tag;
    long long miss = 0;
    explicit Cache(int n) : nlines(n), tag(n, -1) {}
    void access(const void* p) {
        long long t = (long long)((uintptr_t)p / 64);
        int idx = (int)(t % nlines);
        if (tag[idx] != t) { ++miss; tag[idx] = t; }
    }
    void reset() { for (auto& x : tag) x = -1; miss = 0; }
};

struct Particle { float x, y, z, w; };      // AoS：每个粒子 16 字节
const int N = 1024;
Particle                aos[N];             // 数组结构体
alignas(64) float soa_x[N], soa_y[N], soa_z[N], soa_w[N];   // 结构体数组

int main() {
    Cache c(256);

    // AoS：只访问 x 场，却把 y/z/w 一起拉进缓存行 → 浪费带宽
    for (int i = 0; i < N; ++i) c.access(&aos[i].x);
    long long aos_miss = c.miss;

    c.reset();
    // SoA：x 场自身连续，同样访问量下命中的元素多得多
    for (int i = 0; i < N; ++i) c.access(&soa_x[i]);
    long long soa_miss = c.miss;

    printf("AoS 未命中=%lld SoA 未命中=%lld\n", aos_miss, soa_miss);
    printf("SoA 更省缓存行: %d\n", (int)(soa_miss < aos_miss));
    printf("每行可容纳粒子数 AoS=%d SoA=%d\n",
           (int)(64 / sizeof(Particle)), (int)(64 / sizeof(float)));
    return 0;
}
